+'<div class="metric-grid three">'+metric('✓','Approved Prices','0','saved owner approvals will load here','blue')+metric('◷','Needs Review','—','calculated rows awaiting review','amber')+metric('△','Change Requested','0','saved owner requests','red')+'</div>'
+'<div class="card matrix-toolbar">'+field('Family','<select id="matrixFamily"><option value="sup">▣ Stand-Up Pouch</option></select>')+field('Size','<select id="matrixSize">'+options(state.catalog?.sizes||[],state.selectedSize,s=>s.width_mm+' × '+s.height_mm)+'</select>')+field('Printing','<select id="matrixPrint"><option value="CMYKW">◉ CMYKW / configured print process</option><option value="CMYK">CMYK</option></select>')+field('Add On','<select id="matrixAddon"><option value="">No Add On</option><option value="zipper">With Zipper</option></select>')+'<span id="matrixBottomGussetHost"></span>'+field('View Mode','<select id="matrixView"><option>▦ All Prices</option></select>')+'<button class="btn outline" id="matrixReset">↻ Reset Filters</button></div>'
+'<div class="matrix-actions"><button class="btn primary">▧ Review Exceptions</button><button class="btn outline">⇩ Export Matrix</button><button class="btn outline">▧ Compare Previous Version</button></div>'
